return ['x-generator'=>'CF7Apps','translation-revision-date'=>'2026-07-14 00:00:00+0000','plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','project-id-version'=>'CF7 Apps','language'=>'ru','messages'=>['Something is stuck in the honey. Field ID = %1$s (dynamic field: %2$s)'=>'Что-то застряло в мёде. Идентификатор поля = %1$s (динамическое поле: %2$s)','Honeypot detected form submitted without time check. Field ID = %s'=>'Обнаружена форма, отправленная ловушкой для бота без проверки времени. ID поля = %s','Honeypot detected form submitted too fast (%1$s seconds, required: %3$s seconds). Field ID = %2$s'=>'Обнаружена ловушка для бота: форма отправлена слишком быстро (%1$s секунд, требуется: %3$s секунд). ID поля = %2$s','Honeypot detected stale timestamp (replay attack, age: %2$.1f hours). Field ID = %1$s'=>'В ловушке для бота обнаружена устаревшая отметка времени (атака повторного воспроизведения, время прохождения: %2$.1f часов). ID поля = %1$s','Honeypot detected future timestamp (timestamp: %2$s). Field ID = %1$s'=>'Ловушка обнаружила будущую временную метку (timetag: %2$s). Идентификатор поля = %1$s','Honeypot expected dynamic field "%2$s" was missing. Field ID = %1$s'=>'В ловушке для бота отсутствовало динамическое поле %2$s. ID поля = %1$s','Honeypot missing dynamic field metadata. Field ID = %s'=>'У ловушки отсутствуют метаданные динамического поля. Идентификатор поля = %s','Honeypot detected form submitted without valid time check data. Field ID = %s'=>'Обнаружена форма, отправленная в ловушку для бота без действительных данных проверки времени. Идентификатор поля = %s','Honeypot detected invalid or missing random hash. Field ID = %s'=>'В системе ловушки для бота обнаружен неверный или отсутствующий случайный хэш. ID поля = %s','AI returned no form code. Try a clearer description or check middleware logs.'=>'Искусственный интеллект не вернул код формы. Попробуйте дать более понятное описание или проверьте журналы промежуточного ПО.','AI request failed.'=>'Запрос к ИИ не удался.','AI server returned an invalid response.'=>'Сервер ИИ вернул недействительный ответ.','Could not reach AI server: %s'=>'Не удалось подключиться к серверу ИИ: %s','No license key is available for the middleware. Check provision-free response or set CF7APPS_AI_MIDDLEWARE_LICENSE_KEY.'=>'Для промежуточного ПО отсутствует лицензионный ключ. Проверьте ответ без указания условий или установите значение CF7APPS_AI_MIDDLEWARE_LICENSE_KEY.','License provisioning failed.'=>'Сбой при предоставлении лицензии.','Could not provision license: %s'=>'Не удалось предоставить лицензию: %s','The middleware requires a license key, and this site could not obtain one (empty provision secret after filters). Set CF7APPS_AI_MIDDLEWARE_LICENSE_KEY or fix CF7APPS_AI_PROVISION_SECRET.'=>'Для работы промежуточного ПО требуется лицензионный ключ, а этот сайт не смог его получить (пустой секретный ключ после применения фильтров). Установите значение CF7APPS_AI_MIDDLEWARE_LICENSE_KEY или исправьте значение CF7APPS_AI_PROVISION_SECRET.','Please enter form details or select a template to continue.'=>'Пожалуйста, введите данные формы или выберите шаблон, чтобы продолжить.','AI middleware base URL is not set. Define CF7APPS_AI_MIDDLEWARE_BASE_URL in wp-config.php.'=>'Базовый URL промежуточного ПО AI не задан. Определите переменную CF7APPS_AI_MIDDLEWARE_BASE_URL в файле wp-config.php.','AI Form Generator is disabled.'=>'Генератор форм на основе ИИ отключен.','Permission denied.'=>'Доступ запрещен.','Could not copy.'=>'Копирование не удалось.','Copied to clipboard.'=>'Скопировано в буфер обмена.','This field is required.'=>'Это поле обязательно к заполнению.','Reset'=>'Сброс','Insert'=>'Вставить','Copy'=>'Копия','Generated form code'=>'Сгенерированный код формы','e.g., Create a customer feedback form with rating scale, comments section, and contact information fields...'=>'напр.: создайте форму обратной связи с клиентами, содержащую шкалу рейтингов, раздел для комментариев и поля для контактной информации...','Describe the form you want to create'=>'Опишите форму, которую вы хотите создать','Generate Form with AI'=>'Создание формы с помощью ИИ','Create a contact and inquiry form for real estate property listings.'=>'Создайте форму обратной связи и форму запроса для размещения объявлений о продаже недвижимости.','For real estate property listings'=>'Объявления о продаже недвижимости','Contact & Inquiry Form'=>'Форма обратной связи и запросов','Create a customer feedback and rating form for after a purchase.'=>'Создайте форму обратной связи и оценки для клиентов после покупки.','For customers after a purchase'=>'Для клиентов после покупки','Feedback & Rating Form'=>'Форма обратной связи и оценки','Create an appointment booking form for my clinic or healthcare service.'=>'Создайте форму записи на прием в моей клинике или медицинской службе.','For my clinic or healthcare service'=>'Для моей клиники или медицинского учреждения','Appointment Booking Form'=>'Форма записи на прием','Create a job application form for my company\'s career page.'=>'Создайте форму заявки на вакансию для страницы вакансий моей компании.','For my company\'s career page'=>'Для страницы вакансий моей компании','Job Application Form'=>'Заявление о приеме на работу','Enable AI-powered form suggestions for Contact Form 7, allowing users to quickly generate complex form templates with ease.'=>'Включите функцию подсказок на основе искусственного интеллекта для Contact Form 7, которая позволит пользователям быстро и легко создавать сложные шаблоны форм.','Enable AI Form Generator'=>'Включить генератор форм на основе ИИ','Generate Contact Form 7 field tags from a short description or templates, powered by AI.'=>'Создавайте теги полей для Contact Form 7 на основе краткого описания или шаблонов с помощью искусственного интеллекта.','AI Form Generator'=>'Генератор форм на основе ИИ','This integration requires the Advanced Custom Fields plugin to be installed and active.'=>'Для этой интеграции требуется, чтобы плагин Advanced Custom Fields был установлен и активен.','Integrations'=>'Интеграции','This integration requires the Advanced Custom Fields plugin to be installed and active. %s'=>'Для этой интеграции необходимо установить и активировать плагин Advanced Custom Fields. %s','(no title) (ID: %d)'=>'(без заголовка) (ID: %d)','for more settings/info'=>'для получения дополнительных настроек/информации','Generate a form-tag for adding an hCaptcha verification widget to stop spam bots. Check out'=>'Создайте тег формы для добавления виджета проверки hCaptcha, чтобы остановить спам-ботов. Подробнее здесь.','Please enter a field name before inserting the tag.'=>'Пожалуйста, введите название поля перед вставкой тега.','Please select an ACF field from the dropdown before inserting the tag.'=>'Перед вставкой тега выберите поле ACF из выпадающего списка.','Please enter no more than %d characters.'=>'Пожалуйста, введите не более %d символов.','Please enter a number less than or equal to %s.'=>'Пожалуйста, введите число, меньшее или равное %s.','Please enter a number greater than or equal to %s.'=>'Пожалуйста, введите число, большее или равное %s.','Please enter a valid number.'=>'Укажите действующий номер.','ACF field not found.'=>'Поле ACF не найдено.','Advanced Custom Fields plugin is required for this field to work.'=>'Для работы этого поля необходим плагин Advanced Custom Fields.','Should be:'=>'Должно быть:','Current tag:'=>'Текущий тег:','The field key will be automatically added'=>'Ключ поля будет добавлен автоматически','Enter field name and SELECT an ACF field from the dropdown'=>'Введите название поля и выберите поле ACF из выпадающего списка','Click "Insert Tag" → "ACF Field"'=>'Нажмите «Вставить тег» → «Поле ACF»','Delete this tag from your form'=>'Удалите этот тег из вашей формы','How to fix:'=>'Как исправить:','ACF field key is missing from the tag.'=>'В теге отсутствует ключ поля ACF.','ACF Field: Field name is missing.'=>'Поле ACF: Отсутствует название поля.','Field Group'=>'Группа поля','This field key is automatically populated when you select an ACF field above.'=>'Этот ключ поля заполняется автоматически при выборе поля ACF выше.','Select a field above to see the key'=>'Выберите поле выше, чтобы увидеть ключ','Field Key'=>'Ключ поля','The field key will be automatically added when you select a field above.'=>'Ключ поля будет добавлен автоматически при выборе поля выше.','⚠️ Please select an ACF field before inserting the tag.'=>'⚠️ Перед вставкой тега выберите поле ACF.','-- Select ACF Field (Required) --'=>'-- Выберите поле ACF (обязательно) --','Field name'=>'Название поля','Create form-tags using ACF fields to automatically populate and manage dynamic form data. Visit the <a href="%s">ACF Integration settings.</a>'=>'Создавайте теги форм, используя поля ACF, для автоматического заполнения и управления динамическими данными форм. Перейдите в <a href="%s">настройки интеграции ACF</a>','ACF Field'=>'Поле ACF','Please enter a valid URL.'=>'Пожалуйста, введите действительный URL-адрес.','CF7Apps URL'=>'URL CF7Apps','Sets the textarea height'=>'Задает высоту текстового поля','Rows'=>'Ряды','CF7Apps Textarea'=>'CF7Apps Текстовое поле','Character Limit'=>'Ограничение по количеству символов','CF7Apps Text'=>'Текст CF7Apps','Appears after the input'=>'Появляется после ввода','Append'=>'Добавить','Appears before the input'=>'Появляется перед полем ввода','Prepend'=>'Добавить в начало','Increment/decrement amount'=>'Величина увеличения/уменьшения','Step Size'=>'Размер шага','Maximum Value'=>'Максимальное значение','Leave blank for no limit'=>'Оставьте поле пустым, чтобы не было ограничений.','Minimum Value'=>'Минимальное значение','CF7Apps Number'=>'Номер CF7Apps','Please enter a valid email address.'=>'Пожалуйста, введите действительный адрес электронной почты.','Appears within the input'=>'Отображается внутри поля ввода','Placeholder Text'=>'Текст-заполнитель','Appears when creating a new post'=>'Отображается при создании новой записи','Default Value'=>'Значение по умолчанию','CF7Apps Email'=>'CF7Apps Email','When enabled, the ACF integration bridge is created between Contact Form 7 and Advanced Custom Fields.'=>'При включении этой функции создается интеграционный мост ACF между Contact Form 7 и Advanced Custom Fields.','Enable Advanced Custom Fields'=>'Включить расширенные пользовательские поля','ACF Integration'=>'Интеграция ACF','Install ACF Plugin'=>'Установите плагин ACF','This integration requires the Advanced Custom Fields plugin to be active. %s'=>'Для этой интеграции необходимо активировать плагин Advanced Custom Fields. %s','This integration requires the Advanced Custom Fields plugin to be active.'=>'Для этой интеграции требуется, чтобы плагин Advanced Custom Fields был активным.','CF7 Apps ACF Integration:'=>'Интеграция CF7 Apps с ACF:','Connect Advanced Custom Fields with Contact Form 7. Create CF7Apps field types in ACF and use them directly in your CF7 forms.'=>'Подключите расширенные пользовательские поля к Contact Form 7. Создавайте типы полей CF7Apps в ACF и используйте их непосредственно в своих формах CF7.','Advanced Custom Fields'=>'Advanced Custom Fields','Search'=>'Поиск','Share idea'=>'Поделиться идеей','Share your idea with us'=>'Поделитесь с нами своей идеей','View documentation'=>'Просмотреть документацию','Send Contact Form 7 data to third-party apps instantly using webhook endpoints.'=>'Отправляйте данные из Contact Form 7 в сторонние приложения мгновенно, используя конечные точки веб-перехватчиков.','Webhook URL must start with http:// or https://'=>'URL веб-перехватчика должен начинаться с http:// или https://','Webhook URL cannot be empty.'=>'URL веб-перехватчика не может быть пустым.','Use {{form_id}} and {{fields}} placeholders.'=>'Используйте заполнители {{form_id}} и {{fields}}.','Enable Webhook'=>'Включить веб-перехватчик','To create your own body, you can replace values like in mail body (case sensitive).<br>Example: {"message": "Sir [your-name] from [your-city]." }<br><br>We will send your form data as JSON:<br><br><textarea style="width: 500px; min-height: 150px; font-family: monospace; background: #f8f9fa; border: 1px solid #ddd; padding: 10px; pointer-events: none;" readonly>%s</textarea><br><br>This is just an example of field names and will not reflect actual data or customizations.'=>'Чтобы создать собственное тело сообщения, вы можете заменить значения, как в теле письма (с учетом регистра).<br>Пример: {"message": "Сэр [ваше-имя] из [ваш-город]." }<br><br>Мы отправим данные вашей формы в формате JSON:<br><br><textarea style="width: 500px; min-height: 150px; font-family: monospace; background: #f8f9fa; border: 1px solid #ddd; padding: 10px; pointer-events: none;" readonly>%s</textarea><br><br>Это всего лишь пример названий полей и не будет отражать фактические данные или настройки.','When you need customize your request.<br><br><strong style="color: #A61B1B;">BE CAREFUL!</strong> This can break your integration (check your quotes).<br>REMEMBER: You can change field name with webhook config: [email* your_email webhook:email]'=>'Когда вам нужно настроить свой запрос.<br><br><strong style="color: #A61B1B;">БУДЬТЕ ОСТОРОЖНЫ!</strong> Это может нарушить вашу интеграцию (проверьте кавычки).<br>ПОМНИТЕ: Вы можете изменить имя поля в конфигурации веб-хука: [email* your_email webhook:email]','Use {{form_id}} and {{fields}} placeholders. {{fields}} will be a JSON object of submitted fields.'=>'Используйте заполнители {{form_id}} и {{fields}}. {{fields}} будет представлять собой JSON-объект с заполненными полями.','Request Body'=>'Текст запроса','One header by line, separated by colon. Example: Authorization: Bearer 99999999999999999999'=>'Заголовок на каждой строке, разделённый двоеточием. Пример: Authorization: Bearer 99999999999999999999','When you need authentication/authorization.<br>You can add %s to your webhook request.'=>'Когда вам требуется аутентификация/авторизация.<br>Вы можете добавить %s в свой запрос веб-перехватчика.','Optional JSON object of headers to send with the webhook request.'=>'Необязательный JSON-объект с заголовками, которые будут отправлены вместе с запросом веб-перехватчика.','Request Headers'=>'Заголовки запроса','Form Data'=>'Данные формы','JSON'=>'JSON','Data Type'=>'Тип данных','Method'=>'Метод','Webhook URL *'=>'URL веб-перехватчика *','Enable Webhook App'=>'Включить приложение веб-перехватчика','Integration'=>'Интеграция','Webhook'=>'Веб-перехватчик','Redirection settings not found.'=>'Настройки перенаправления не найдены.','Redirection is not enabled for this form.'=>'Для этой формы перенаправление не включено.','Enable Redirection'=>'Включить перенаправление','Internal URL'=>'Внутренний URL','Enable global settings, so they apply across all forms. These global settings will automatically sync with each individual form, where they can still be modified if needed.'=>'Включите глобальные настройки, чтобы они применялись ко всем формам. Эти глобальные настройки будут автоматически синхронизироваться с каждой отдельной формой, и при необходимости их можно будет изменить.','spam submissions since'=>'спам-сообщения с тех пор','Honeypot has stopped'=>'Работа ловушки для бота приостановлена','To Enable, Go to Settings'=>'Чтобы включить эту функцию, перейдите в Настройки','Redirection app is not enabled.'=>'Приложение для перенаправления не включено.','Form ID is required.'=>'Требуется идентификатор формы.','Open the redirection link in a new browser tab.'=>'Откройте ссылку перенаправления в новой вкладке браузера.','Open in New Tab'=>'Открыть в новой вкладке','Enter the external URL to redirect users to after form submission. Make sure to include the full URL (e.g., https://example.com).'=>'Введите внешний URL-адрес, на который будут перенаправлены пользователи после отправки формы. Обязательно укажите полный URL-адрес (например, https://example.com).','Choose the post type to redirect users to after form submission.'=>'Выберите тип записи, на которую будут перенаправлены пользователи после отправки формы.','Select Post Type'=>'Выберите тип записи','External URL'=>'Внешний URL','Redirection Type'=>'Тип перенаправления','Global Settings'=>'Глобальные настройки','Enable Redirection App'=>'Включить приложение перенаправления','Easily redirect users to a specific URL after form submission, enhancing user experience and engagement.'=>'Удобная переадресация пользователей на определенный URL-адрес после отправки формы улучшает пользовательский опыт и вовлеченность.','Redirection'=>'Перенаправление','Stuck? Check our Documentation on %s'=>'Возникли трудности? Ознакомьтесь с нашей документацией по %s','Page'=>'Страница','entries'=>'записи','Showing'=>'Показано','No records found.'=>'Записи не найдены.','View'=>'Вид','Date & Time'=>'Дата и время','Email'=>'Электронная почта','Form Name'=>'Название формы','Clear Filter'=>'Очистить фильтр','Select Date Range'=>'Выберите диапазон дат','Apply'=>'Применять','Please select at least one entry'=>'Пожалуйста, выберите хотя бы один вариант ответа','Delete'=>'Удалить','Bulk Actions'=>'Массовые действия','No data found.'=>'Данные не найдены.','Values'=>'Значения','Fields'=>'Поля','Email Details'=>'Информация об электронной почте','An error occurred while deleting entries'=>'Произошла ошибка при удалении записей','Failed to delete entries'=>'Не удалось удалить записи','Entries deleted successfully'=>'Записи успешно удалены','Are you sure you want to delete the selected entries?'=>'Вы уверены, что хотите удалить выбранные записи?','Please select an action'=>'Пожалуйста, выберите действие','An error occurred while deleting the entry'=>'Произошла ошибка при удалении записи','Failed to delete entry'=>'Не удалось удалить запись','Entry deleted successfully'=>'Запись успешно удалена','Are you sure you want to delete this entry?'=>'Вы уверены, что хотите удалить эту запись?','Close'=>'Закрыть','All Forms'=>'Все формы','Show Entries'=>'Показать записи','Entries Settings'=>'Настройки записей','Access and manage all Contact Form 7 submissions in a centralized database with filtering and export options.'=>'Получайте доступ ко всем отправленным через Contact Form 7 данным и управляйте ими в централизованной базе данных с возможностью фильтрации и экспорта.','Entries'=>'Записи','CF7 Apps'=>'Приложения CF7','No forms found.'=>'Формы не найдены.','%s Settings'=>'Настройки %s','Error! Something Went Wrong'=>'Ошибка! Что-то пошло не так','Great! Settings Saved Successfully'=>'Отлично! Настройки успешно сохранены','Error! Please fill all required fields.'=>'Ошибка! Пожалуйста, заполните все обязательные поля.','Please fill all required fields.'=>'Пожалуйста, заполните все обязательные поля.','Spam Protection Apps'=>'Приложения для защиты от спама','Simplify, customize, and enhance your form building experience.'=>'Упростите, настройте и улучшите процесс создания форм.','Unleash the full potential of Contact Form 7!'=>'Раскройте весь потенциал Contact Form 7!','Yes, Migrate to CF7 Apps'=>'Да, переходите на приложения CF7','You can still use both, but we recommend switching now.'=>'Вы по-прежнему можете использовать оба варианта, но мы рекомендуем переключиться на другой сейчас.','For enhanced security and additional features, we have developed CF7 Apps. You can now move your Honeypot settings to the new Honeypot App inside CF7 Apps.'=>'Для повышения безопасности и расширения функционала мы разработали CF7 Apps. Теперь вы можете перенести настройки вашей ловушки Honeypot в новое приложение Honeypot, входящее в состав CF7 Apps.','Attention: Introducing CF7 Apps 🎉'=>'Внимание: Представляем приложения CF7 🎉','Oops! Migration failed, please try again.'=>'Ой! Миграция не удалась, пожалуйста, попробуйте еще раз.','Great! Migration completed successfully, Enjoy CF7 Apps 🥳.'=>'Отлично! Миграция успешно завершена. Наслаждайтесь приложениями CF7 🥳.','Show More'=>'Показать больше','Show Less'=>'Показать меньше','Back'=>'Назад','Disabled'=>'Отключить','Enabled'=>'Включено','Learn more'=>'Узнать больше','App disabled'=>'Приложение отключено','App enabled'=>'Приложение включено','CF7 Apps\' Honeypot App.'=>'Приложение Honeypot от CF7 Apps.','We\'ve moved your Honeypot settings to the Honeypot App in CF7 Apps. You can still use both, but we recommend using the'=>'Мы перенесли ваши настройки Honeypot в приложение Honeypot в разделе приложений CF7. Вы по-прежнему можете использовать оба приложения, но мы рекомендуем использовать Honeypot.','Welcome to CF7 Apps!'=>'Добро пожаловать в CF7 Apps!','No'=>'Нет','Yes'=>'Да','Install Contact Form 7'=>'Установите Contact Form 7','%s requires Contact Form 7 to be installed and activated. %s'=>'Для работы %s требуется установленная и активированная версия Contact Form 7. %s','Time Check Value (Seconds)'=>'Контрольная величина времени (в секундах)','If checked, the accessibility label will not be generated. This is not recommended, but may improve.'=>'Если этот параметр отмечен, метка доступности не будет сгенерирована. Это не рекомендуется, но может улучшить ситуацию.','By default Honeypot uses inline CSS on the honeypot field to hide it. Checking this box moves.'=>'По умолчанию Honeypot использует встроенный CSS в поле приманки, чтобы скрыть его. Установка этого флажка перемещается.','To assure the honeypot isn\'t auto-completed by a browser, we add an atypical "autocomplete" .'=>'Чтобы гарантировать, что ловушка не будет автоматически дополняться браузером, мы добавляем нетипичный механизм "автозаполнения".','You can customize the (hidden) accessibility message, or just leave it the default value: Please leave this field empty.'=>'Вы можете настроить (скрытое) сообщение о доступности или просто оставить для него значение по умолчанию: Оставьте это поле пустым.','(Recommended) By default the Honeypot field is not stored with other fields in form-saving plugins like Flamingo. However, saving the field can be useful to see what spam bots are leaving behind to help you improve your spam stopping superpowers. If you\'d like to store the value of the field, simply check this box (and install Flamingo).'=>'(Рекомендуется) По умолчанию поле Honeypot не сохраняется вместе с другими полями в плагинах сохранения форм, таких как Flamingo. Однако сохранение этого поля может быть полезно для просмотра того, что оставляют спам-боты, и поможет вам улучшить эффективность защиты от спама. Если вы хотите сохранить значение поля, просто установите этот флажок (и установите Flamingo).','Enable Honeypot App'=>'Включить приложение Honeypot','Add invisible honeypot fields to your forms to trap spambots, ensuring spam-free form submission.'=>'Добавьте в свои формы невидимые поля-ловушки для спам-ботов, чтобы обеспечить отправку форм без спама.','Choose the theme for the hCaptcha widget.'=>'Выберите тему оформления для виджета hCaptcha.','Dark'=>'Темный','Light'=>'Светлый','Theme'=>'Тема','Add custom CSS classes to the hCaptcha widget.'=>'Добавьте пользовательские CSS-классы к виджету hCaptcha.','Custom CSS'=>'Пользовательский CSS','Choose the size of the hCaptcha widget.'=>'Выберите размер виджета hCaptcha.','Compact'=>'Компактный','Normal'=>'Нормальный','Size'=>'Размер','Language'=>'Язык','Error message'=>'Сообщение ошибке','Documentation'=>'Документация','Need help setting this up? Check out our'=>'Нужна помощь в настройке? Ознакомьтесь с нашими','Save Settings'=>'Сохраните настройки','Choose a language for your CAPTCHA display.'=>'Выберите язык для отображения CAPTCHA.','Force hCaptcha to render in a specific language.'=>'Принудительно отображать hCaptcha на определенном языке.','Enter a custom message to display when CAPTCHA validation fails.'=>'Введите пользовательское сообщение, которое будет отображаться при неудачной проверке CAPTCHA.','Invalid Captcha'=>'Неверная капча','Invalid Captcha error message'=>'Сообщение об ошибке "Неверная капча"','Enter your secret key. Don\'t have one? <a href="https://dashboard.hcaptcha.com/settings/secrets" target="_blank">Click here</a> to generate a new key.'=>'Введите свой секретный ключ. У вас его нет? <a href="https://dashboard.hcaptcha.com/settings/secrets" target="_blank">Нажмите здесь</a>, чтобы сгенерировать новый ключ.','Secret key is required.'=>'Требуется секретный ключ.','Secret Key'=>'Секретный ключ','Enter your site key. Don\'t have one? <a href="https://dashboard.hcaptcha.com/sites" target="_blank">Click here</a> to generate a new key.'=>'Введите ключ вашего сайта. У вас его нет? <a href="https://dashboard.hcaptcha.com/sites" target="_blank">Нажмите здесь</a>, чтобы сгенерировать новый ключ.','Site key is required.'=>'Требуется ключ сайта.','Site Key'=>'Ключ сайта','Enable hCaptcha App'=>'Включить приложение hCaptcha','hCaptcha Settings'=>'настройки hCaptcha','Spam Protection'=>'Защита от спама','Add hCaptcha to Contact Form 7 for secure, spam-free forms.'=>'Добавьте hCaptcha в Contact Form 7 для создания безопасных форм, защищенных от спама.','hCaptcha'=>'hCaptcha','Zulu'=>'Зулусский','Yoruba'=>'Йоруба','Yiddish'=>'Идиш','Xhosa'=>'Коса','Welsh'=>'Валлийский','Vietnamese'=>'Вьетнамский','Uzbek'=>'Узбекский','Urdu'=>'Урду','Ukrainian'=>'Украинский','Uyghur'=>'Уйгур','Turkmen'=>'Туркменский','Turkish'=>'Турецкий','Thai'=>'Тайский','Teluga'=>'Телуга','Tatar'=>'Татарский','Tamil'=>'Тамильский','Tajik'=>'Таджикский','Tagalog'=>'Тагальский','Swedish'=>'Шведский','Swahili'=>'Суахили','Sundanese'=>'Сунданский','Spanish'=>'Испанский','Southern Sotho'=>'Северный сото','Somali'=>'Сомали','Slovenian'=>'Словенский','Slovak'=>'Словацкий','Serbian'=>'Сербский','Sinhalese'=>'Сингальский','Sindhi'=>'Синдхи','Shona'=>'Шона','Samoan'=>'Самоанский','Russian'=>'Русский','Romanian'=>'Румынский','Punjabi'=>'Панджабский','Pashto'=>'Пушту','Portuguese'=>'Португальский','Polish'=>'Польский','Oriya'=>'Орийский','Nyanja'=>'Ньянджа','Norwegian'=>'Норвежский','Nepali'=>'Непальский','Montenegrin (as Bosnian)'=>'Черногорский (как боснийский)','Mongolian'=>'Монгольский','Marathi'=>'Маратхский','Maori'=>'Маори','Maltese'=>'Мальтийский','Malayalam'=>'Малайялам','Malay'=>'Малайский','Malagasy'=>'Малагасийский','Macedonian'=>'Македонский','Luxembourgish'=>'Люксембургский','Lithuanian'=>'Литовский','Latvian'=>'Латвийский','Latin'=>'Латиница','Lao'=>'Лаосский','Kurdish'=>'Курдский','Korean'=>'Корейский','Kirghiz'=>'Киргизский','Kinyarwanda'=>'Киньяруандский','Khmer'=>'Кхмерский','Kazakh'=>'Казахский','Kannada'=>'Каннада','Javanese'=>'Яванский','Japanese'=>'Японская','Italian'=>'Итальянский','Irish'=>'Ирландский','Indonesian'=>'Индонезийский','Igbo'=>'Игбо','Icelandic'=>'Исландский','Hungarian'=>'Венгерский','Hmong'=>'Хмонг','Hindi'=>'Хинди','Hebrew'=>'Иврит','Hawaiian'=>'Гавайский','Hausa'=>'Хауса','Haitian'=>'Гаитянский','Gujurati'=>'Гуджарати','Greek'=>'Греческий','German'=>'Немецкий','Georgian'=>'Грузинский','Galacian'=>'Галисийский','Gaelic'=>'Гэльский','Frisian'=>'Фризский','French'=>'Французский','Finnish'=>'Финский','Farsi/ Persian'=>'Фарси/Персидский','Estonian'=>'Эстонский','Esperanto'=>'Эсперанто','English'=>'Английский','Dutch'=>'Голландский','Danish'=>'Датский','Czech'=>'Чешский','Croatian'=>'Хорватский','Corsican'=>'Корсиканский','Chinese Traditional'=>'Китайский традиционный','Chinese Simplified'=>'Китайский упрощенный','Chinese'=>'Китайский','Cebuano'=>'Себуанский','Catalan'=>'Каталонский','Burmese'=>'Бирманский','Bosnian'=>'Боснийский','Bulgarian'=>'Болгарский','Bengali'=>'Бенгальский','Belarusian'=>'Беларусский','Basque'=>'Баскский','Azerbaijani'=>'Азербайджанский','Armenian'=>'Армянский','Arabic'=>'Арабский','Amharic'=>'Амхарский','Albanian'=>'Албанский','Afrikaans'=>'Африканский','Contact Form 7 Apps is a collection of useful modules and extensions for Contact Form 7.'=>'Contact Form 7 Apps — это набор полезных модулей и расширений для Contact Form 7.','https://cf7apps.com/'=>'https://cf7apps.com/','disable Accessibility Label'=>'отключить Метку Доступности','Edit'=>'Изменить','no'=>'нет','yes'=>'да','Action'=>'Действие','Date'=>'Дата','Shortcode'=>'Быстрый код','Title'=>'Название','Forms'=>'Формы','General'=>'Общие','Move inline CSS'=>'Переместить встроенный CSS','Placeholder'=>'Подсказка','Wrapper ID'=>'ID обёртки','Class'=>'Класс','ID'=>'ID','Optional Settings'=>'Дополнительные настройки','For better security, change "honeypot" to something more appealing to a bot, such as text including "email" or "website".'=>'Для большей безопасности измените «приманку» на что-то более привлекательное для бота, например текст, включающий «email» или «website».','Generate a form-tag for a spam-stopping honeypot field. Check out %s for more settings/info.'=>'Создайте тег формы для поля приманки для предотвращения спама. Проверьте %s для получения дополнительных настроек/информации.','Honeypot for CF7'=>'Honeypot for CF7','Honeypot has stopped %1$s spam submissions since %2$s'=>'Honeypot остановил отправку спама %1$s с %2$s','Reset to Defaults'=>'Восстановить настройки по умолчанию','Save'=>'Сохранить','If enabled, this will perform an additional check for spam bots using the time it takes to submit the form under the idea that bots submit forms faster than people. The value is set to 4 seconds by default, but adjust based on your needs. If you\'re not sure, leave this unchecked.'=>'Если этот параметр включен, будет выполняться дополнительная проверка спам-ботов с использованием времени, необходимого для отправки формы, поскольку боты отправляют формы быстрее, чем люди. Значение установлено на 4 секунды по умолчанию, но настраивайте его в соответствии с вашими потребностями. Если вы не уверены, не устанавливайте этот флажок.','seconds'=>'секунды','Enable Time Check'=>'Включить проверку времени','Disable Accessibility Label'=>'Отключить ярлык доступности','By default Honeypot uses inline CSS on the honeypot field to hide it. Checking this box moves that CSS to the footer of the page. It may help confuse bots.'=>'По умолчанию Honeypot использует встроенный CSS в поле honeypot, чтобы скрыть его. Установка этого флажка перемещает этот CSS в нижний колонтитул страницы. Это может помочь запутать ботов.','Move Inline CSS'=>'Переместить встроенный CSS','To assure the honeypot isn\'t auto-completed by a browser, we add an atypical "autocomplete" attribute value. If you have any problems with this, you can switch it to the more standard (but less effective) "off" value. If you\'re unsure, leave this unchecked.'=>'Чтобы убедиться, что браузер не заполняет приманку автоматически, мы добавляем нетипичное значение атрибута «autocomplete». Если у вас возникли проблемы с этим, вы можете переключить его на более стандартное (но менее эффективное) значение «off». Если вы не уверены, не устанавливайте этот флажок.','Use Standard Autocomplete Value'=>'Используйте стандартное значение автозаполнения','You can customize the (hidden) accessibility message, or just leave it the default value: %s'=>'Вы можете настроить (скрытое) сообщение о специальных возможностях или просто оставить значение по умолчанию: %s','Accessibility Message'=>'Сообщение о доступности','If using placeholders on other fields, this can help honeypot mimic a "real" field. This can be overridden in the contact form. If you\'re unsure, leave blank.'=>'При использовании заполнителей в других полях это может помочь приманке имитировать «настоящее» поле. Это можно переопределить в контактной форме. Если вы не уверены, оставьте поле пустым.','Global Placeholder'=>'Глобальный заполнитель','Flamingo'=>'Flamingo','(Recommended) By default the Honeypot field is not stored with other fields in form-saving plugins like %1$s. However, saving the field can be useful to see what spam bots are leaving behind to help you improve your spam stopping superpowers. If you\'d like to store the value of the field, simply check this box (and install %1$s).'=>'(Рекомендуется) По умолчанию поле Honeypot не хранится вместе с другими полями в плагинах для сохранения форм, таких как %1$s. Тем не менее, сохранение поля может быть полезно, чтобы увидеть, что оставляют спам-боты, чтобы помочь вам улучшить свои суперсилы по борьбе со спамом. Если вы хотите сохранить значение поля, просто установите этот флажок (и установите %1$s).','Store Honeypot Value'=>'Сохранение значения приманки','Below are global settings for the Honeypot plugin. Many of these settings can be overridden when inserting the Honeypot field shortcode when creating your CF7 contact form.'=>'Ниже приведены глобальные настройки плагина Honeypot. Многие из этих настроек могут быть переопределены при вставке шорткода поля Honeypot при создании контактной формы CF7.','Honeypot Settings'=>'Настройки Honeypot','Get Support'=>'Получить поддержку','The changes have been saved.'=>'Изменения были сохранены.','The settings have been reset to their defaults.'=>'Настройки были сброшены на значения по умолчанию.','Settings'=>'Настройки','The version of %s that is installed will not work with this version of Honeypot for CF7.'=>'Установленная версия %s не будет работать с этой версией Honeypot для CF7.','Contact Form 7'=>'Contact Form 7','Honeypot for Contact Form 7'=>'Honeypot for Contact Form 7','If checked, the accessibility label will not be generated. This is not recommended, but may improve spam blocking. If you\'re unsure, leave this unchecked.'=>'Если флажок установлен, метка доступности не будет создаваться. Это не рекомендуется, но может улучшить блокировку спама. Если вы не уверены, оставьте этот флажок не отмеченным.','Insert Tag'=>'Вставить метку','Name'=>'Название','Generate a form-tag for a spam-stopping honeypot field. For more details, see %s.'=>'Генерирует тег формы для поля, препятствующего спаму. Для получения более подробной информации см. раздел %s.','Honeypot'=>'Honeypot (ловушка для спамботов)','Please leave this field empty.'=>'Оставьте это поле пустым.','%s must be installed and activated for the CF7 Honeypot plugin to work'=>'%s должен быть установлен и активирован для работы плагина CF7 Honeypot','Expand sidebar'=>'Развернуть боковую панель','Collapse sidebar'=>'Свернуть боковую панель','Quick Access'=>'Быстрый доступ','Open Support Ticket'=>'Открыть заявку в поддержку','Help Center'=>'Справочный центр','Leave Us a Review'=>'Оставить отзыв','Supercharge Your Workflow'=>'Ускорьте свой рабочий процесс','Dashboard sidebar'=>'Боковая панель панели управления','CF7 Apps navigation'=>'Навигация CF7 Apps','CF7 Apps form settings navigation'=>'Навигация настроек формы CF7 Apps','Back to Dashboard'=>'Назад к панели управления','Back to all apps'=>'Назад ко всем приложениям','Go back'=>'Назад','Beta'=>'Бета','All'=>'Все','Payment'=>'Оплата','Search apps'=>'Поиск приложений','Filter apps'=>'Фильтр приложений','No apps match your search or filter.'=>'Нет приложений, соответствующих поиску или фильтру.','Enable app'=>'Включить приложение','Disable app'=>'Отключить приложение','Conditional Redirection'=>'Условное перенаправление','Conditional redirection will redirect users based on specific form field values or submission conditions. Upgrade to PRO to unlock this feature.'=>'Условное перенаправление отправляет пользователей на разные страницы в зависимости от значений полей формы или условий отправки. Обновитесь до PRO, чтобы разблокировать эту функцию.','PRO'=>'PRO','Silent Success for Blocked Bots'=>'Тихий успех для заблокированных ботов','When enabled, submissions blocked by the honeypot will receive a normal success response instead of a spam error. No email is sent, but bots are less likely to detect the honeypot.'=>'Если включено, отправки, заблокированные honeypot, получат обычный ответ об успехе вместо ошибки спама. Письмо не отправляется, но ботам сложнее обнаружить ловушку.','Recommended for high-spam sites. Real users incorrectly blocked will also see a success message.'=>'Рекомендуется для сайтов с большим количеством спама. Настоящие пользователи, заблокированные по ошибке, также увидят сообщение об успехе.','When 